// /sitemap.xml is generated by the Supabase `sitemap` edge function, but Supabase's
// gateway rewrites its Content-Type to text/plain. Vercel proxies it through
// api/sitemap.ts so crawlers receive application/xml.
//
// NOTE: relative imports only - Vercel's bundler does not resolve "@/".

export async function proxySitemap(
  req: Request,
  supabaseUrl: string | undefined,
  f: typeof fetch = fetch,
): Promise<Response> {
  if (!supabaseUrl) return new Response("sitemap unavailable", { status: 503, headers: { "Cache-Control": "no-store" } });

  const part = new URL(req.url).searchParams.get("part");
  const target = `${supabaseUrl.replace(/\/$/, "")}/functions/v1/sitemap${part ? `?part=${encodeURIComponent(part)}` : ""}`;

  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 15000);
  try {
    const upstream = await f(target, { signal: ctrl.signal });
    const body = await upstream.text();
    if (!upstream.ok || !body.startsWith("<?xml")) {
      return new Response("sitemap unavailable", { status: 502, headers: { "Cache-Control": "no-store" } });
    }
    return new Response(body, {
      status: 200,
      headers: {
        "Content-Type": "application/xml; charset=utf-8",
        "Cache-Control": "public, max-age=0, s-maxage=3600, stale-while-revalidate=86400",
      },
    });
  } catch {
    return new Response("sitemap unavailable", { status: 502, headers: { "Cache-Control": "no-store" } });
  } finally {
    clearTimeout(timer);
  }
}
